import { readdirSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { describe, expect, it } from "vitest";

import {
  conversationSynthesis,
  type ConversationSynthesisInput,
} from "../src/prompts/index.js";

// Generated by the data plane's Python synthesis builder, which this builder
// replaces: the same messages, events and sections, the same digest and the
// same resume state, though not the same bytes everywhere.
const FIXTURES = join(
  dirname(fileURLToPath(import.meta.url)),
  "fixtures",
  "conversation-synthesis",
);

interface Fixture {
  name: string;
  input: ConversationSynthesisInput;
  expected: {
    prompt?: string;
    plan?: Record<string, unknown>;
    outcome?: Record<string, unknown>;
  };
}

/** Keep `timestamp_ns` exact: it is past what a JSON number holds. */
function load(file: string): Fixture {
  return JSON.parse(
    readFileSync(join(FIXTURES, file), "utf8"),
    (key, value, context?: { source?: string }) =>
      key === "timestamp_ns" &&
      typeof value === "number" &&
      context?.source !== undefined
        ? context.source
        : value,
  ) as Fixture;
}

/** What the prompt is made of: its sections, messages by role, and events by kind. */
function shape(prompt: string) {
  return {
    sections: [...prompt.matchAll(/^ {2}<(\w+)/gm)].map((m) => m[1]),
    messages: [...prompt.matchAll(/<message ref="(\w+)" role="(\w+)">/g)].map(
      (m) => `${m[1]}:${m[2]}`,
    ),
    events: [...prompt.matchAll(/<event ref="(\w+)" kind="(\w+)">/g)].map(
      (m) => `${m[1]}:${m[2]}`,
    ),
  };
}

/** A resume state with its instants compared as instants, whatever their format. */
function instants(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(instants);
  if (value === null || typeof value !== "object") return value;
  return Object.fromEntries(
    Object.entries(value).map(([key, item]) => [
      key,
      (key === "watermark" || key === "completed_at") &&
      typeof item === "string"
        ? Date.parse(item)
        : instants(item),
    ]),
  );
}

describe("conversation_synthesis@1 reads a conversation as the Python builder did", () => {
  for (const file of readdirSync(FIXTURES).filter((name) =>
    name.endsWith(".json"),
  )) {
    const fixture = load(file);
    it(fixture.name, () => {
      const built = conversationSynthesis.build(fixture.input, 1_000_000);
      if (fixture.expected.prompt === undefined) {
        expect(instants(built.state)).toEqual(
          instants({ outcome: fixture.expected.outcome }),
        );
        return;
      }
      const ours = shape(built.prompt);
      const theirs = shape(fixture.expected.prompt);
      expect(ours.sections).toEqual(theirs.sections);
      if (theirs.sections.includes("transcript_capped")) {
        // Sizes are estimated as JSON in each language, so the cap's boundary
        // moves by a few messages: the head and the tail are what it keeps.
        expect(ours.messages.slice(0, 10)).toEqual(
          theirs.messages.slice(0, 10),
        );
        expect(ours.messages.slice(-100)).toEqual(theirs.messages.slice(-100));
        expect(ours.messages.length / theirs.messages.length).toBeGreaterThan(
          0.95,
        );
      } else {
        expect(ours).toEqual(theirs);
      }
      const { digest: ourDigest, ...ourPlan } = (
        built.state as { plan: Record<string, unknown> }
      ).plan;
      const { digest: theirDigest, ...theirPlan } = fixture.expected.plan!;
      expect(instants(ourPlan)).toEqual(instants(theirPlan));
      // The digest hashes the messages the cap kept, so only a capped case differs.
      if (!theirs.sections.includes("transcript_capped")) {
        expect(ourDigest).toBe(theirDigest);
      }
    });
  }
});
